// Shared helpers for every game: sounds, confetti, home button, progress,
// start/celebration screens. No network, no storage, no tracking.
const Juegos = (() => {
  // ---------- Sound (generated by the browser, no audio files) ----------
  let audioCtx = null;

  function getAudio() {
    if (!audioCtx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return null;
      audioCtx = new AudioCtx();
    }
    if (audioCtx.state === "suspended") audioCtx.resume();
    return audioCtx;
  }

  function tone(freq, duration, { type = "sine", volume = 0.2, slideTo = null, delay = 0 } = {}) {
    const ac = getAudio();
    if (!ac) return;
    const start = ac.currentTime + delay;
    const osc = ac.createOscillator();
    const gain = ac.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, start);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(slideTo, start + duration);
    gain.gain.setValueAtTime(volume, start);
    gain.gain.exponentialRampToValueAtTime(0.001, start + duration);
    osc.connect(gain).connect(ac.destination);
    osc.start(start);
    osc.stop(start + duration + 0.05);
  }

  const sound = {
    pop() {
      tone(450 + Math.random() * 300, 0.14, { slideTo: 1300, volume: 0.25 });
    },
    star() {
      tone(880, 0.12, { type: "triangle" });
      tone(1320, 0.22, { type: "triangle", delay: 0.08 });
    },
    click() {
      tone(660, 0.08, { type: "square", volume: 0.08 });
    },
    oops() {
      tone(300, 0.2, { type: "triangle", slideTo: 200, volume: 0.15 });
    },
    win() {
      [523, 659, 784, 1047].forEach((f, i) =>
        tone(f, 0.35, { type: "triangle", delay: i * 0.14, volume: 0.25 })
      );
    },
  };

  // ---------- Visual effects ----------
  const CONFETTI_COLORS = ["#f43f5e", "#f59e0b", "#22c55e", "#3b82f6", "#a855f7", "#ec4899"];

  function removeOnEnd(el) {
    el.addEventListener("animationend", () => el.remove(), { once: true });
  }

  // Small emoji particles flying out of a point (e.g. a popped bubble).
  function burst(x, y, emoji = "✨", count = 8) {
    for (let i = 0; i < count; i++) {
      const p = document.createElement("div");
      p.className = "particle";
      p.textContent = emoji;
      const angle = (Math.PI * 2 * i) / count;
      const dist = 70 + Math.random() * 50;
      p.style.left = `${x - 14}px`;
      p.style.top = `${y - 14}px`;
      p.style.setProperty("--dx", `${Math.cos(angle) * dist}px`);
      p.style.setProperty("--dy", `${Math.sin(angle) * dist}px`);
      document.body.appendChild(p);
      removeOnEnd(p);
    }
  }

  // Confetti rain over the whole screen.
  function confetti(count = 80) {
    for (let i = 0; i < count; i++) {
      const c = document.createElement("div");
      c.className = "confetti";
      c.style.left = `${Math.random() * window.innerWidth}px`;
      c.style.top = `${-30 - Math.random() * 60}px`;
      c.style.background = CONFETTI_COLORS[i % CONFETTI_COLORS.length];
      c.style.animationDelay = `${Math.random() * 0.4}s`;
      c.style.setProperty("--dx", `${(Math.random() - 0.5) * 200}px`);
      c.style.setProperty("--dy", `${window.innerHeight * (0.7 + Math.random() * 0.4)}px`);
      c.style.setProperty("--rot", `${Math.random() * 720}deg`);
      document.body.appendChild(c);
      removeOnEnd(c);
    }
  }

  // ---------- UI pieces ----------
  function homeButton(href = "../index.html") {
    const a = document.createElement("a");
    a.href = href;
    a.className = "home-btn";
    a.textContent = "🏠";
    a.setAttribute("aria-label", "Volver al inicio");
    document.body.appendChild(a);
  }

  // A row of `total` stars; call set(n) to light the first n.
  function progress(total, emoji = "⭐") {
    const bar = document.createElement("div");
    bar.className = "progress";
    const stars = [];
    for (let i = 0; i < total; i++) {
      const s = document.createElement("span");
      s.textContent = emoji;
      bar.appendChild(s);
      stars.push(s);
    }
    document.body.appendChild(bar);
    return {
      set(n) {
        stars.forEach((s, i) => s.classList.toggle("on", i < n));
      },
    };
  }

  function medals() {
    const box = document.createElement("div");
    box.className = "medals";
    document.body.appendChild(box);
    return {
      add(emoji = "🏅") {
        box.textContent += emoji;
      },
    };
  }

  // Overlay with a big emoji (or element) and a green play button. Resolves on click.
  function overlay(emoji) {
    return new Promise((resolve) => {
      const layer = document.createElement("div");
      layer.className = "overlay";
      const big = document.createElement("div");
      big.className = "big-emoji";
      if (emoji instanceof Node) big.appendChild(emoji);
      else big.textContent = emoji;
      const btn = document.createElement("button");
      btn.className = "play-btn";
      btn.textContent = "▶";
      btn.setAttribute("aria-label", "Jugar");
      btn.addEventListener("click", () => {
        sound.click();
        layer.remove();
        resolve();
      });
      layer.append(big, btn);
      document.body.appendChild(layer);
    });
  }

  function startScreen(emoji) {
    return overlay(emoji);
  }

  function celebrate(emoji = "🎉") {
    sound.win();
    confetti();
    return overlay(emoji);
  }

  // Right-click shows a friendly "green button" hint instead of a menu.
  function guardRightClick() {
    window.addEventListener("contextmenu", (e) => {
      e.preventDefault();
      sound.oops();
      const hint = document.createElement("div");
      hint.className = "wrong-button-hint";
      hint.textContent = "🟢🖱️";
      hint.style.left = `${e.clientX}px`;
      hint.style.top = `${e.clientY}px`;
      document.body.appendChild(hint);
      removeOnEnd(hint);
    });
  }

  function bubbleIcon() {
    const el = document.createElement("span");
    el.className = "bubble-look bubble-icon";
    return el;
  }

  function random(min, max) {
    return min + Math.random() * (max - min);
  }

  function pick(list) {
    return list[Math.floor(Math.random() * list.length)];
  }

  return { sound, burst, confetti, homeButton, progress, medals, startScreen, celebrate, guardRightClick, bubbleIcon, random, pick };
})();
